 8 | use tower_http::trace::TraceLayer;
 9 | use serde::{Deserialize, Serialize};
10 | use std::sync::Mutex;
11 | 
12 | #[derive(Clone)]
13 | struct AppState {
14 |     users: Mutex<Vec<User>>,
15 | }
16 | 
17 | #[derive(Serialize, Deserialize, Clone)]
18 | struct User {
19 |     id: u64,
20 |     name: String,
21 |     email: String,
22 | }
23 | 
24 | #[derive(Deserialize)]
25 | struct ListQuery {
26 |     limit: Option<u64>,
27 | }
28 | 
29 | #[tokio::main]
30 | async fn main() {
31 |     let state = AppState {
32 |         users: Mutex::new(Vec::new()),
33 |     };
34 | 
35 |     let app = Router::new()
36 |         .route("/users", get(list_users).post(create_user))
37 |         .route("/users/{id}", get(get_user).delete(delete_user))
38 |         .layer(TraceLayer::new_for_http())
39 |         .with_state(state);
40 | 
41 |     let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").await.unwrap();
42 |     axum::serve(listener, app).await.unwrap();
43 | }
44 | 
45 | async fn list_users(
46 |     State(state): State<AppState>,
47 |     query: Query<ListQuery>,
48 | ) -> Json<Vec<User>> {
49 |     let users = state.users.lock().unwrap();
50 |     let limit = query.limit.unwrap_or(100);
51 |     let result: Vec<_> = users.iter().take(limit as usize).cloned().collect();
52 |     Json(result)
53 | }
54 | 
55 | async fn create_user(
56 |     State(state): State<AppState>,
57 |     body: Json<User>,
58 | ) -> (StatusCode, Json<User>) {
59 |     let mut users = state.users.lock().unwrap();
60 |     let user = body.0.clone();
61 |     users.push(user.clone());
62 |     (StatusCode::CREATED, Json(user))
63 | }
64 | 
65 | async fn get_user(
66 |     State(state): State<AppState>,
67 |     Path(id): Path<u64>,
68 | ) -> Result<Json<User>, (StatusCode, Json<serde_json::Value>)> {
69 |     let users = state.users.lock().unwrap();
70 |     match users.iter().find(|u| u.id == id) {
71 |         Some(user) => Ok(Json(user.clone())),
72 |         None => Err((
73 |             StatusCode::NOT_FOUND,
74 |             Json(serde_json::json!({"error": "not found"})),
75 |         )),
76 |     }
77 | }
78 | 
79 | async fn delete_user(
80 |     State(state): State<AppState>,
81 |     Path(id): Path<u64>,
82 | ) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
83 |     let mut users = state.users.lock().unwrap();
84 |     let len_before = users.len();
85 |     users.retain(|u| u.id != id);
86 |     if users.len() < len_before {
87 |         Ok(StatusCode::NO_CONTENT)
88 |     } else {
89 |         Err((
90 |             StatusCode::NOT_FOUND,
91 |             Json(serde_json::json!({"error": "not found"})),
92 |         ))
93 |     }
94 | }

