14 |     pub directions: Vec<bool>,
15 | }
16 | 
17 | impl<H: Digest + Clone + Debug> MerkleTree<H> {
18 |     pub fn new(leaves: &[&[u8]]) -> Self {
19 |         assert!(!leaves.is_empty(), "leaves cannot be empty");
20 |         let hashed: Vec<[u8; 32]> = leaves.iter().map(|l| {
21 |             let mut hasher = H::new();
22 |             hasher.update(l);
23 |             let res = hasher.finalize();
24 |             let mut arr = [0u8; 32];
25 |             arr.copy_from_slice(&res);
26 |             arr
27 |         }).collect();
28 |         let mut layers = vec![hashed];
29 |         while layers.last().unwrap().len() > 1 {
30 |             let prev = layers.last().unwrap();
31 |             let mut next = Vec::new();
32 |             let mut i = 0;
33 |             while i < prev.len() {
34 |                 let left = prev[i];
35 |                 let right = prev.get(i + 1).copied().unwrap_or(left);
36 |                 let mut hasher = H::new();
37 |                 hasher.update(left);
38 |                 hasher.update(right);
39 |                 let res = hasher.finalize();
40 |                 let mut arr = [0u8; 32];
41 |                 arr.copy_from_slice(&res);
42 |                 next.push(arr);
43 |                 i += 2;
44 |             }
45 |             layers.push(next);
46 |         }
47 |         Self { layers, _hasher: std::marker::PhantomData }
48 |     }
49 | 
50 |     pub fn root(&self) -> [u8; 32] {
51 |         self.layers.last().unwrap()[0]
52 |     }
53 | 
54 |     pub fn proof(&self, leaf_index: usize) -> MerkleProof {
55 |         let mut idx = leaf_index;
56 |         let mut siblings = Vec::new();
57 |         let mut directions = Vec::new();
58 |         for layer in &self.layers[..self.layers.len() - 1] {
59 |             let sibling_idx = if idx % 2 == 0 { idx + 1 } else { idx - 1 };
60 |             let sibling = layer.get(sibling_idx).copied().unwrap_or(layer[idx]);
61 |             siblings.push(sibling);
62 |             directions.push(idx % 2 == 0);
63 |             idx /= 2;
64 |         }
65 |         MerkleProof { leaf_index, siblings, directions }
66 |     }
67 | 
68 |     pub fn verify(proof: &MerkleProof, root: &[u8; 32]) -> bool {
69 |         let mut current = proof.siblings.get(0)
70 |             .map(|_| [0u8; 32]) // placeholder
71 |             .unwrap_or([0u8; 32]);
72 |         // BUG: we need the leaf hash, not a placeholder
73 |         for (i, (sibling, go_right)) in proof.siblings.iter().zip(proof.directions.iter()).enumerate() {
74 |             let mut hasher = H::new();
75 |             if *go_right {
76 |                 hasher.update(&current);
77 |                 hasher.update(sibling);
78 |             } else {
79 |                 hasher.update(sibling);
80 |                 hasher.update(&current);
81 |             }
82 |             let res = hasher.finalize();
83 |             current.copy_from_slice(&res);
84 |         }
