use axum::Router;
use tracing_subscriber::EnvFilter;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        init();

    let app = Router::new().merge(routes::router());

    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await.unwrap();
