  3 | export interface WebSocketConfig {
  4 |   url: string;
  5 |   protocols?: string | string[];
  6 | }
  7 | 
  8 | export class WebSocketClient extends EventEmitter {
  9 |   private ws: WebSocket | null = null;
  10 |   private config: WebSocketConfig;
  11 |   private isConnected: boolean = false;
  12 | 
  13 |   constructor(config: WebSocketConfig) {
  14 |     super();
  15 |     this.config = config;
  16 |   }
  17 | 
  18 |   connect(): void {
  19 |     this.ws = new WebSocket(this.config.url, this.config.protocols);
  20 |     this.ws.onopen = () => this.handleOpen();
  21 |     this.ws.onclose = () => this.handleClose();
  22 |     this.ws.onerror = (err) => this.handleError(err);
  23 |     this.ws.onmessage = (msg) => this.handleMessage(msg);
  24 |   }
  25 | 
  26 |   disconnect(): void {
  27 |     if (this.ws) {
  28 |       this.ws.close();
  29 |       this.ws = null;
  30 |     }
  31 |   }
  32 | 
  33 |   send(data: string | ArrayBuffer | Blob): void {
  34 |     if (this.ws && this.isConnected) {
  35 |       this.ws.send(data);
  36 |     }
  37 |   }
  38 | 
  39 |   private handleOpen(): void {
  40 |     this.isConnected = true;
  41 |     this.emit('open');
  42 |   }
  43 | 
  44 |   private handleClose(): void {
  45 |     this.isConnected = false;
  46 |     this.emit('close');
  47 |   }
  48 | 
  49 |   private handleError(err: Event): void {
  50 |     this.emit('error', err);
  51 |   }
  52 | 
  53 |   private handleMessage(msg: MessageEvent): void {
  54 |     this.emit('message', msg);
  55 |   }
  56 | }

