   4  use crate::actors::coordinator::CoordMsg;
   5  use crate::actors::coordinator::CoordinatorHandle;
   6  
   7  pub enum RouterMsg {
   8      Route { key: String, oneshot::Sender<RouteResult> },
   9      Forward { payload: Vec<u8>, oneshot::Sender<ForwardResult> },
  10     Broadcast { correlation_id: u64, oneshot::Sender<BroadcastResult> },
  11 }
  12 
  13 pub struct RouterActor {
  14     rx: mpsc::Receiver<RouterMsg>,
  15     coordinator: CoordinatorHandle,
  16 }
  17 
  18 impl RouterActor {
  19     pub fn new(rx: mpsc::Receiver<RouterMsg>, coordinator: CoordinatorHandle) -> Self {
  20         Self { rx, coordinator }
  21     }
  22 
  23     pub async fn run(&mut self) {
  24         while let Some(msg) = self.rx.recv().await {
  25             match msg {
  26                 RouterMsg::Route { key, tx } => {
  27                     // DEADLOCK: router calls coordinator.call() while
  28                     // coordinator may be simultaneously calling router.call()
  29                     let resp = self.coordinator.call(CoordMsg::Route { key, tx }).await.unwrap();
  30                     // ... handle resp
  31                 },
  32                 RouterMsg::Forward { payload, tx } => {
  33                     let resp = self.coordinator.call(CoordMsg::Forward { payload, tx }).await.unwrap();
  34                     // ... handle resp
  35                 },
  36                 RouterMsg::Broadcast { correlation_id, tx } => {
  37                     // process broadcast locally, then respond
  38                     let result = self.process_broadcast(correlation_id).await;
  39                     let _ = tx.send(result);
  40                 },
  41             }
  42         }
  43     }
  44 
  45     async fn process_broadcast(&self, _id: u64) -> BroadcastResult {
  46         BroadcastResult::Ok
  47     }
  48 }

