 5 |
 6 | #[derive(Parser)]
 7 | #[command(name = "qnote")]
 8 | #[command(about = "Quick notes from the terminal", long_about = None)]
 9 | struct Cli {
10 |     #[command(subcommand)]
11 |     command: Commands,
12 |
13 |     /// Notes directory
14 |     #[arg(long, global = true, default_value = "~/.qnote")]
15 |     dir: PathBuf,
16 | }
17 |
18 | #[derive(Subcommand)]
19 | enum Commands {
20 |     /// Add a new note
21 |     Add {
22 |         /// Note content
23 |         #[arg(short, long)]
24 |         message: String,
25 |
26 |         /// Tags (comma-separated)
27 |         #[arg(short, long, default_value = "")]
28 |         tags: String,
29 |     },
30 |     /// List all notes
31 |     List {
32 |         /// Filter by tag
33 |         #[arg(short, long)]
34 |         tag: Option<String>,
35 |     },
36 |     /// Remove a note by id
37 |     Rm {
38 |         /// Note ID
39 |         id: u64,
40 |     },
41 | }
42 |
43 | #[derive(Serialize, Deserialize, Debug)]
44 | struct Note {
45 |     id: u64,
46 |     message: String,
47 |     tags: Vec<String>,
48 |     created: String,
49 | }
50 |
51 | fn main() {
52 |     let cli = Cli::parse();
53 |     println!("{:#?}", cli);
54 | }

