use actix_service::{Service, Transform};
use actix_web::{HttpRequest, HttpResponse, Error};
use futures_util::future::{LocalBoxFuture, ok, Ready};
use std::rc::Rc;
use std::task::{Context, Poll};
use tracing::warn;

pub struct RequestId;

impl<S, B> Transform<S, actix_web::dev::ServiceRequest> for RequestId
where
    S: Service<actix_web::dev::ServiceRequest, Response = actix_web::dev::ServiceResponse<B>, Error = Error>,
    S::Future: 'static,
    B: 'static,
{
    type Response = actix_web::dev::ServiceResponse<B>;
    type Error = Error;
    type Transform = RequestIdMiddleware<S>;
    type InitError = ();
    type Future = Ready<Result<Self::Transform, Self::InitError>>;

    fn new_transform(&self, service: S) -> Self::Future {
        ok(RequestIdMiddleware { service: Rc::new(service) })
    }
}

pub struct RequestIdMiddleware<S> {
    service: Rc<S>,
}

impl<S, B> Service<actix_web::dev::ServiceRequest> for RequestIdMiddleware<S>
where
    S: Service<actix_web::dev::ServiceRequest, Response = actix_web::dev::ServiceResponse<B>, Error = Error>,
    S::Future: 'static,
    B: 'static,
{
    type Response = actix_web::dev::ServiceResponse<B>;
    type Error = Error;
    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;

    fn poll_ready(&self, ctx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.service.poll_ready(ctx)
    }

    fn call(&self, req: actix_web::dev::ServiceRequest) -> Self::Future {
        let svc = self.service.clone();
        let request_id = uuid::Uuid::new_v4().to_string();
        req.headers_mut().insert(
            actix_web::http::header::HeaderName::from_static("x-request-id"),
            actix_web::http::header::HeaderValue::from_str(&request_id).unwrap(),
        );
        Box::pin(async move {
            let res = svc.call(req).await?;
            Ok(res)
        })
    }
}

pub struct AuthCheck;

impl<S, B> Transform<S, actix_web::dev::ServiceRequest> for AuthCheck
where
    S: Service<actix_web::dev::ServiceRequest, Response = actix_web::dev::ServiceResponse<B>, Error = Error>,
    S::Future: 'static,
    B: 'static,
{
    type Response = actix_web::dev::ServiceResponse<B>;
    type Error = Error;
    type Transform = AuthCheckMiddleware<S>;
    type InitError = ();
    type Future = Ready<Result<Self::Transform, Self::InitError>>;

    fn new_transform(&self, service: S) -> Self::Future {
        ok(AuthCheckMiddleware { service: Rc::new(service) })
    }
}

pub struct AuthCheckMiddleware<S> {
    service: Rc<S>,
}

impl<S, B> Service<actix_web::dev::ServiceRequest> for AuthCheckMiddleware<S>
where
    S: Service<actix_web::dev::ServiceRequest, Response = actix_web::dev::ServiceResponse<B>, Error = Error>,
    S::Future: 'static,
    B: 'static,
{
    type Response = actix_web::dev::ServiceResponse<B>;
    type Error = Error;
    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;

    fn poll_ready(&self, ctx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.service.poll_ready(ctx)
    }

    fn call(&self, req: actix_web::dev::ServiceRequest) -> Self::Future {
        let svc = self.service.clone();
        let auth_header = req.headers().get("authorization");

        if auth_header.is_none() {
            warn!("Missing authorization header on {}", req.path());
            return Box::pin(async {
                Ok(req.into_response(HttpResponse::Unauthorized().json(serde_json::json!({
                    "error": "missing authorization header"
                })).into_body()))
            });
        }

        Box::pin(async move {
            let res = svc.call(req).await?;
            Ok(res)
        })
    }
}
