	db *db.DB
}

func (r *OrderRepo) GetByUserID(ctx context.Context, userID string) ([]Order, error) {
	rows, err := r.db.Query(ctx,
		"SELECT id, user_id, total, status, created_at FROM orders WHERE user_id = $1",
		userID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	collect := pgx.RowToStructByNameLax[Order]
	return pgx.CollectRows(rows, collect)
}
