1 | pub struct InnerActor {
  2 |     coordinator: CoordinatorActorHandle,
  3 |     cache: HashMap<String, String>,
  4 |     rx: mpsc::Receiver<InnerMsg>,
  5 | }
  6 | 
  7 | impl InnerActor {
  8 |     pub async fn run(&mut self) {
  9 |         while let Some(msg) = self.rx.recv().await {
 10 |             match msg {
 11 |                 InnerMsg::Get { key, reply } => {
 12 |                     let span = tracing::info_span!("inner_actor", "get", key = %key);
 13 |                     let _guard = span.enter();
 14 |                     if let Some(v) = self.cache.get(&key) {
 15 |                         tracing::debug!("cache hit");
 16 |                         reply.send(Ok(v.clone())).unwrap();
 17 |                         continue;
 18 |                     }
 19 |                     tracing::debug!("cache miss, requesting reload from coordinator");
 20|                     let val = self.coordinator.send(CoordinatorMsg::Reload { key }).await?;
 21|                     // ^^^ DEADLOCK: coordinator.handle_reload locks inner_lock (L47),
 22|                     // but we're inside InnerActor::run which is the only task
 23|                     // processing InnerMsg. inner_lock.lock() blocks forever.
 24|                     self.cache.insert(key, val.clone());
 25|                     reply.send(Ok(val)).unwrap();
 26|                 }
 27|                 InnerMsg::Invalidate { key, reply } => {
 28|                     let _ = self.cache.remove(&key);
 29|                     reply.send(Ok(())).unwrap();
 30|                 }
 31|             }
 32|         }
 33|     }
 34| }

