use std::sync::Arc;
use tokio::sync::mpsc;
use tokio_tungstenite::tungstenite::Message;

pub struct Client {
    pub id: String,
    pub username: String,
    pub room_name: String,
    tx: mpsc::UnboundedSender<String>,
}

impl Client {
    pub fn new(id: String, username: String, room_name: String, tx: mpsc::UnboundedSender<String>) -> Self {
        Self { id, username, room_name, tx }
    }

    pub async fn send(&self, msg: String) -> Result<(), mpsc::error::SendError<String>> {
        self.tx.send(msg)
    }
}

pub struct ClientHandle {
    pub client: Arc<Client>,
    pub rx: mpsc::UnboundedReceiver<String>,
}

impl ClientHandle {
    pub fn create(id: String, username: String, room_name: String) -> (Arc<Client>, Self) {
        let (tx, rx) = mpsc::unbounded_channel();
        let client = Arc::new(Client::new(id, username, room_name, tx));
        let handle = Self { client, rx };
        (client, handle)
    }
}
