 31 | }
 32 | 
 33 | pub struct CircuitBreaker {
 34 |     config: Config,
 34 |     state: std::sync::Mutex<State>,
 35 |     failure_count: AtomicU64,
 36 |     success_count: AtomicU64,
 37 |     half_open_requests: AtomicU64,
 38 |     last_failure: std::sync::Mutex<Option<Instant>>,
 39 | }
 40 | 
 41 | impl CircuitBreaker {
 42 |     pub fn new(config: Config) -> Self {
 43 |         Self {
 44 |             config,
 45 |             state: std::sync::Mutex::new(State::Closed),
 46 |             failure_count: AtomicU64::new(0),
 47 |             success_count: AtomicU64::new(0),
 48 |             half_open_requests: AtomicU64::new(0),
 49 |             last_failure: std::sync::Mutex::new(None),
 50 |         }
 51 |     }
 52 | 
 53 |     pub fn state(&self) -> Result<State, CircuitBreakerError> {
 54 |         let state = self.state.lock().map_err(|_| CircuitBreakerError::PoisonedLock)?;
 55 |         Ok(*state)
 56 |     }
 57 | 
 58 |     pub fn allow_request(&self) -> Result<bool, CircuitBreakerError> {
 59 |         let mut state = self.state.lock().map_err(|_| CircuitBreakerError::PoisonedLock)?;
 60 |         match *state {
 61 |             State::Closed => Ok(true),
 62 |             State::Open => {
 63 |                 let last_failure = self.last_failure.lock().map_err(|_| CircuitBreakerError::PoisonedLock)?;
 64 |                 if let Some(t) = *last_failure {
 65 |                     if t.elapsed() >= self.config.open_timeout {
 66 |                         *state = State::HalfOpen;
 67 |                         self.half_open_requests.store(0, Ordering::SeqCst);
 68 |                         Ok(true)
 69 |                     } else {
 70 |                         Ok(false)
 71 |                     }
 72 |                 } else {
 73 |                     Ok(false)
 74 |                 }
 75 |             }
 76 |             State::HalfOpen => {
 77 |                 let current = self.half_open_requests.fetch_add(1, Ordering::SeqCst);
 78 |                 Ok(current < self.config.half_open_max_requests)
 79 |             }
 80 |         }
 81 |     }
 82 | 
 83 |     pub fn record_success(&self) -> Result<(), CircuitBreakerError> {
 84 |         let mut state = self.state.lock().map_err(|_| CircuitBreakerError::PoisonedLock)?;
 85 |         match *state {
 86 |             State::Closed => {
 87 |                 self.failure_count.store(0, Ordering::SeqCst);
 88 |                 Ok(())
 89 |             }
 90 |             State::HalfOpen => {
 91 |                 let successes = self.success_count.fetch_add(1, Ordering::SeqCst) + 1;
 92 |                 if successes >= self.config.success_threshold {
 93 |                     *state = State::Closed;
 94 |                     self.failure_count.store(0, Ordering::SeqCst);
 95 |                     self.success_count.store(0, Ordering::SeqCst);
 96 |                 }
 97 |                 Ok(())
 98 |             }
 99 |             State::Open => Ok(()),
100 |         }
101 |     }
102 | 
103 |     pub fn record_failure(&self) -> Result<(), CircuitBreakerError> {
104 |         let mut state = self.state.lock().map_err(|_| CircuitBreakerError::PoisonedLock)?;
105 |         let mut last_failure = self.last_failure.lock().map_err(|_| CircuitBreakerError::PoisonedLock)?;
106 |         match *state {
107 |             State::Closed => {
108 |                 let failures = self.failure_count.fetch_add(1, Ordering::SeqCst) + 1;
109 |                 if failures >= self.config.failure_threshold {
110 |                     *state = State::Open;
111 |                     *last_failure = Some(Instant::now());
112 |                 }
113 |                 Ok(())
114 |             }
115 |             State::HalfOpen => {
116 |                 *state = State::Open;
117 |                 *last_failure = Some(Instant::now());
118 |                 self.success_count.store(0, Ordering::SeqCst);
119 |                 self.half_open_requests.store(0, Ordering::SeqCst);
120 |                 Ok(())
121 |             }
122 |             State::Open => Ok(()),
123 |         }
124 |     }
125 | }

