+    #[test]
+    fn test_refill_over_time() {
+        let mut bucket = TokenBucket::new(10, 10); // 10 tokens/sec
+        assert!(bucket.try_consume(10));
+        // Simulate 500ms passing — should get 5 tokens back
+        std::thread::sleep(std::time::Duration::from_millis(500));
+        assert!(bucket.try_consume(5));
+    }
+
+    #[test]
+    fn test_wait_time_calculation() {
+        let mut bucket = TokenBucket::new(10, 10);
+        bucket.try_consume(10);
+        let wait = bucket.wait_time(5);
+        assert!(wait.as_millis() <= 500);
+        assert!(wait.as_millis() >= 400);
+    }
+
+    #[test]
+    fn test_capacity_capped() {
+        let mut bucket = TokenBucket::new(10, 100);
+        // Wait enough to overfill
+        std::thread::sleep(std::time::Duration::from_millis(200));
+        assert_eq!(bucket.available_tokens(), 10); // should cap at capacity
+    }
